use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit: int = 200000
    let mut sieve: Vec<bool> = []
    let mut i: int = 0
    while i <= limit {
        sieve.push(true)
        i += 1
    }
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut c: int = 0
    let mut last: int = -1
    let mut p: int = 0
    while p <= limit {
        if p >= 2 && sieve[p as usize] {
            c += 1
            last = p
            let mut m: int = p * p
            while m <= limit {
                sieve[m as usize] = false
                m += p
            }
        }
        counts.push(c)
        largest.push(last)
        p += 1
    }
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        let k = counts[n as usize]
        if k == 0 {
            println("0 none")
        } else {
            println("${k} ${largest[n as usize]}")
        }
    }
}

